230	pub(super) fn create_initiation<R: RngCore + CryptoRng, O>(
231	    rng: &mut R,
232	    keyst: &KeyState,
233	    peer: &Peer<O>,
234	    pk: &PublicKey,
235	    local: u32,
236	    msg: &mut NoiseInitiation,
237	) -> Result<(), HandshakeError> {
238	    log::debug!("create initiation");
239	
240	    // check for zero shared-secret (see "shared_secret" note).
241	    if peer.ss.ct_eq(&[0u8; 32]).into() {
242	        return Err(HandshakeError::InvalidSharedSecret);
243	    }
244	
245	    clear_stack_on_return_fnonce(CLEAR_PAGES, || {
246	        // initialize state
247	
248	        let ck = INITIAL_CK;
249	        let hs = INITIAL_HS;
250	        let hs = HASH!(&hs, pk.as_bytes());
251	
252	        msg.f_type.set(TYPE_INITIATION as u32);
253	        msg.f_sender.set(local); // from us
254	
255	        // (E_priv, E_pub) := DH-Generate()
256	
257	        let eph_sk = StaticSecret::new(rng);
258	        let eph_pk = PublicKey::from(&eph_sk);
259	
260	        // C := Kdf(C, E_pub)
261	
262	        let ck = KDF1!(&ck, eph_pk.as_bytes());
263	
264	        // msg.ephemeral := E_pub
265	
266	        msg.f_ephemeral = *eph_pk.as_bytes();
267	
268	        // H := HASH(H, msg.ephemeral)
269	
270	        let hs = HASH!(&hs, msg.f_ephemeral);
271	
272	        // (C, k) := Kdf2(C, DH(E_priv, S_pub))
273	
274	        let (ck, key) = KDF2!(&ck, shared_secret(&eph_sk, &pk)?.as_bytes());
275	
276	        // msg.static := Aead(k, 0, S_pub, H)
277	
278	        SEAL!(
279	            &key,
280	            &hs,                 // ad
281	            keyst.pk.as_bytes(), // pt
282	            &mut msg.f_static    // ct || tag
283	        );
284	
285	        // H := Hash(H || msg.static)
286	
287	        let hs = HASH!(&hs, &msg.f_static[..]);
288	
289	        // (C, k) := Kdf2(C, DH(S_priv, S_pub))
290	
291	        let (ck, key) = KDF2!(&ck, &peer.ss);
292	
293	        // msg.timestamp := Aead(k, 0, Timestamp(), H)
294	
295	        SEAL!(
296	            &key,
297	            &hs,                  // ad
298	            &timestamp::now(),    // pt
299	            &mut msg.f_timestamp  // ct || tag
300	        );
301	
302	        // H := Hash(H || msg.timestamp)
303	
304	        let hs = HASH!(&hs, &msg.f_timestamp);
305	
306	        // update state of peer
307	
308	        *peer.state.lock() = State::InitiationSent {
309	            hs,
310	            ck,
311	            eph_sk,
312	            local,
313	        };
314	
315	        Ok(())
316	    })
317	}
318	
319	pub(super) fn consume_initiation<'a, O>(
320	    device: &'a Device<O>,
321	    keyst: &KeyState,
322	    msg: &NoiseInitiation,
323	) -> Result<(&'a Peer<O>, PublicKey, TemporaryState), HandshakeError> {
324	    log::debug!("consume initiation");
325	
326	    clear_stack_on_return_fnonce(CLEAR_PAGES, || {
327	        // initialize new state
328	
329	        let ck = INITIAL_CK;
330	        let hs = INITIAL_HS;
331	        let hs = HASH!(&hs, keyst.pk.as_bytes());
332	
333	        // C := Kdf(C, E_pub)
334	
335	        let ck = KDF1!(&ck, &msg.f_ephemeral);
336	
337	        // H := HASH(H, msg.ephemeral)
338	
339	        let hs = HASH!(&hs, &msg.f_ephemeral);
340	
341	        // (C, k) := Kdf2(C, DH(E_priv, S_pub))
342	
343	        let eph_r_pk = PublicKey::from(msg.f_ephemeral);
344	        let (ck, key) = KDF2!(&ck, shared_secret(&keyst.sk, &eph_r_pk)?.as_bytes());
345	
346	        // msg.static := Aead(k, 0, S_pub, H)
347	
348	        let mut pk = [0u8; 32];
349	
350	        OPEN!(
351	            &key,
352	            &hs,           // ad
353	            &mut pk,       // pt
354	            &msg.f_static  // ct || tag
355	        )?;
356	
357	        let peer = device.lookup_pk(&PublicKey::from(pk))?;
358	
359	        // check for zero shared-secret (see "shared_secret" note).
360	
361	        if peer.ss.ct_eq(&[0u8; 32]).into() {
362	            return Err(HandshakeError::InvalidSharedSecret);
363	        }
364	
365	        // reset initiation state
366	
367	        *peer.state.lock() = State::Reset;
368	
369	        // H := Hash(H || msg.static)
370	
371	        let hs = HASH!(&hs, &msg.f_static[..]);
372	
373	        // (C, k) := Kdf2(C, DH(S_priv, S_pub))
374	
375	        let (ck, key) = KDF2!(&ck, &peer.ss);
376	
377	        // msg.timestamp := Aead(k, 0, Timestamp(), H)
378	
379	        let mut ts = timestamp::ZERO;
380	
381	        OPEN!(
382	            &key,
383	            &hs,              // ad
384	            &mut ts,          // pt
385	            &msg.f_timestamp  // ct || tag
386	        )?;
387	
388	        // check and update timestamp
389	
390	        peer.check_replay_flood(device, &ts)?;
391	
392	        // H := Hash(H || msg.timestamp)
393	
394	        let hs = HASH!(&hs, &msg.f_timestamp);
395	
396	        // return state (to create response)
397	
398	        Ok((
399	            peer,
400	            PublicKey::from(pk),
401	            (msg.f_sender.get(), eph_r_pk, hs, ck),
402	        ))
403	    })
404	}
405	
406	pub(super) fn create_response<R: RngCore + CryptoRng, O>(
407	    rng: &mut R,
408	    peer: &Peer<O>,
409	    pk: &PublicKey,
410	    local: u32,              // sending identifier
411	    state: TemporaryState,   // state from "consume_initiation"
412	    msg: &mut NoiseResponse, // resulting response
413	) -> Result<KeyPair, HandshakeError> {
414	    log::debug!("create response");
415	    clear_stack_on_return_fnonce(CLEAR_PAGES, || {
416	        // unpack state
417	
418	        let (receiver, eph_r_pk, hs, ck) = state;
419	
420	        msg.f_type.set(TYPE_RESPONSE as u32);
421	        msg.f_sender.set(local); // from us
422	        msg.f_receiver.set(receiver); // to the sender of the initiation
423	
424	        // (E_priv, E_pub) := DH-Generate()
425	
426	        let eph_sk = StaticSecret::new(rng);
427	        let eph_pk = PublicKey::from(&eph_sk);
428	
429	        // C := Kdf1(C, E_pub)
430	
431	        let ck = KDF1!(&ck, eph_pk.as_bytes());
432	
433	        // msg.ephemeral := E_pub
434	
435	        msg.f_ephemeral = *eph_pk.as_bytes();
436	
437	        // H := Hash(H || msg.ephemeral)
438	
439	        let hs = HASH!(&hs, &msg.f_ephemeral);
440	
441	        // C := Kdf1(C, DH(E_priv, E_pub))
442	
443	        let ck = KDF1!(&ck, shared_secret(&eph_sk, &eph_r_pk)?.as_bytes());
444	
445	        // C := Kdf1(C, DH(E_priv, S_pub))
446	
447	        let ck = KDF1!(&ck, shared_secret(&eph_sk, &pk)?.as_bytes());
448	
449	        // (C, tau, k) := Kdf3(C, Q)
450	
451	        let (ck, tau, key) = KDF3!(&ck, &peer.psk);
452	
453	        // H := Hash(H || tau)
454	
455	        let hs = HASH!(&hs, tau);
456	
457	        // msg.empty := Aead(k, 0, [], H)
458	
459	        SEAL!(
460	            &key,
461	            &hs,              // ad
462	            &[],              // pt
463	            &mut msg.f_empty  // \epsilon || tag
464	        );
465	
466	        // Not strictly needed
467	        // let hs = HASH!(&hs, &msg.f_empty_tag);
468	
469	        // derive key-pair
470	
471	        let (key_recv, key_send) = KDF2!(&ck, &[]);
472	
473	        // return unconfirmed key-pair
474	
475	        Ok(KeyPair {
476	            birth: Instant::now(),
477	            initiator: false,
478	            send: Key {
479	                id: receiver,
480	                key: key_send.into(),
481	            },
482	            recv: Key {
483	                id: local,
484	                key: key_recv.into(),
485	            },
486	        })
487	    })
488	}
489	
490	/* The state lock is released while processing the message to
491	 * allow concurrent processing of potential responses to the initiation,
492	 * in order to better mitigate DoS from malformed response messages.
493	 */
494	pub(super) fn consume_response<'a, O>(
495	    device: &'a Device<O>,
496	    keyst: &KeyState,
497	    msg: &NoiseResponse,
498	) -> Result<Output<'a, O>, HandshakeError> {
499	    log::debug!("consume response");
500	    clear_stack_on_return_fnonce(CLEAR_PAGES, || {
501	        // retrieve peer and copy initiation state
502	        let (peer, _) = device.lookup_id(msg.f_receiver.get())?;
503	
504	        let (hs, ck, local, eph_sk) = match *peer.state.lock() {
505	            State::InitiationSent {
506	                hs,
507	                ck,
508	                local,
509	                ref eph_sk,
510	            } => Ok((hs, ck, local, StaticSecret::from(eph_sk.to_bytes()))),
511	            _ => Err(HandshakeError::InvalidState),
512	        }?;
513	
514	        // C := Kdf1(C, E_pub)
515	
516	        let ck = KDF1!(&ck, &msg.f_ephemeral);
517	
518	        // H := Hash(H || msg.ephemeral)
519	
520	        let hs = HASH!(&hs, &msg.f_ephemeral);
521	
522	        // C := Kdf1(C, DH(E_priv, E_pub))
523	
524	        let eph_r_pk = PublicKey::from(msg.f_ephemeral);
525	        let ck = KDF1!(&ck, shared_secret(&eph_sk, &eph_r_pk)?.as_bytes());
526	
527	        // C := Kdf1(C, DH(E_priv, S_pub))
528	
529	        let ck = KDF1!(&ck, shared_secret(&keyst.sk, &eph_r_pk)?.as_bytes());
530	
531	        // (C, tau, k) := Kdf3(C, Q)
532	
533	        let (ck, tau, key) = KDF3!(&ck, &peer.psk);
534	
535	        // H := Hash(H || tau)
536	
537	        let hs = HASH!(&hs, tau);
538	
539	        // msg.empty := Aead(k, 0, [], H)
540	
541	        OPEN!(
542	            &key,
543	            &hs,          // ad
544	            &mut [],      // pt
545	            &msg.f_empty  // \epsilon || tag
546	        )?;
547	
548	        // derive key-pair
549	
550	        let birth = Instant::now();
551	        let (key_send, key_recv) = KDF2!(&ck, &[]);
552	
553	        // check for new initiation sent while lock released
554	
555	        let mut state = peer.state.lock();
556	        let update = match *state {
557	            State::InitiationSent {
558	                eph_sk: ref old, ..
559	            } => old.to_bytes().ct_eq(&eph_sk.to_bytes()).into(),
560	            _ => false,
561	        };
562	
563	        if update {
564	            // null the initiation state
565	            // (to avoid replay of this response message)
566	            *state = State::Reset;
567	            let remote = msg.f_sender.get();
568	
569	            // return confirmed key-pair
570	            Ok((
571	                Some(&peer.opaque),
572	                None,
573	                Some(KeyPair {
574	                    birth,
575	                    initiator: true,
576	                    send: Key {
577	                        id: remote,
578	                        key: key_send.into(),
579	                    },
580	                    recv: Key {
581	                        id: local,
582	                        key: key_recv.into(),
583	                    },
584	                }),
585	            ))
586	        } else {
587	            Err(HandshakeError::InvalidState)
588	        }
589	    })
590	}
